<script setup lang="ts">
import { computed,ref } from 'vue';import type { MonthlyReconciliationSummary } from '@shared/types/payroll';import EmptyState from '../components/EmptyState.vue';import MoneyValue from '../components/MoneyValue.vue';import PageHeader from '../components/PageHeader.vue';import { errorMessage } from '../utils/errorMessage';
const year=ref(new Date().getFullYear());const loading=ref(false);const consulted=ref(false);const error=ref('');const items=ref<MonthlyReconciliationSummary[]>([]);
const rows=computed(()=>Array.from({length:12},(_,index)=>{const month=index+1;const monthItems=items.value.filter(i=>i.month===month);return{month,total:monthItems.reduce((s,i)=>s+i.totalAmountCents,0),groups:monthItems.length,files:monthItems.reduce((s,i)=>s+i.fileCount,0)};}));
const annualTotal=computed(()=>rows.value.reduce((s,r)=>s+r.total,0));async function consult():Promise<void>{loading.value=true;error.value='';try{const response=await window.sefiplanApi.getMonthlyHistory({page:1,pageSize:100,year:year.value});items.value=response.items;consulted.value=true;}catch(cause){error.value=errorMessage(cause,'No se pudo consultar la matriz anual.');}finally{loading.value=false;}}
</script><template><PageHeader title="Matriz anual" description="Compara los totales mensuales vigentes del ejercicio." /><div v-if="error" class="alert alert-danger">{{ error }}</div><form class="period-toolbar" @submit.prevent="consult"><div><label class="form-label" for="matrix-year">Año</label><input id="matrix-year" v-model.number="year" class="form-control" type="number" min="2000" max="2200" /></div><button class="btn btn-primary align-self-end" :disabled="loading">Consultar</button></form><EmptyState v-if="!consulted" title="Selecciona un año" description="Consulta los expedientes mensuales vigentes." icon="bi-calendar3" /><div v-else class="table-responsive table-frame"><table class="table align-middle mb-0"><thead><tr><th>Mes</th><th class="text-end">Grupos</th><th class="text-end">Archivos activos</th><th class="text-end">Total</th></tr></thead><tbody><tr v-for="row in rows" :key="row.month"><td>{{ new Date(year,row.month-1,1).toLocaleDateString('es-MX',{month:'long'}) }}</td><td class="text-end">{{ row.groups }}</td><td class="text-end">{{ row.files }}</td><td class="text-end"><MoneyValue :cents="row.total" /></td></tr></tbody><tfoot><tr><th colspan="3">Total anual</th><th class="text-end"><MoneyValue :cents="annualTotal" /></th></tr></tfoot></table></div></template>
